(async () => {
  const pool = getPool();
  const result = await pool.query(
    `select device_id, display_name, note, availability, net_mode, ap_ip, sta_ip, sta_connected, uart_baud, fw_version, last_seen_at, updated_at,
       case
         when last_seen_at is null then 'unknown'
         when last_seen_at >= now() - interval '60 seconds' then 'online'
         when last_seen_at >= now() - interval '5 minutes' then 'stale'
         else 'offline'
       end as cloud_state
     from devices
     order by
       case
         when last_seen_at >= now() - interval '60 seconds' then 0
         when last_seen_at >= now() - interval '5 minutes' then 1
         when last_seen_at is null then 3
         else 2
       end,
       last_seen_at desc nulls last,
       device_id asc`
  );
  const summary = { total: result.rows.length, online: 0, stale: 0, offline: 0, unknown: 0 };
  for (const row of result.rows) {
    summary[row.cloud_state] = (summary[row.cloud_state] || 0) + 1;
  }
  msg.payload = { ok: true, generated_at: new Date().toISOString(), summary, devices: result.rows };
  return msg;
})().then((out) => node.send(out)).then(() => node.done()).catch((err) => {
  msg.statusCode = 500;
  msg.payload = { ok: false, message: err.message };
  node.send(msg);
  node.error(err, msg);
  node.done(err);
});
return;

